import App, { Reaction } from './'
import assert from 'assert'
import { state, moduleState } from './tags'

describe('Reaction', () => {
  // Basic state watching tests
  it('should watch state', () => {
    let grabbedValue = 0
    const foo = Reaction({ foo: state`foo` }, ({ foo }) => {
      grabbedValue = foo
    })
    const app = {
      reactions: { foo },
      state: { foo: 'bar' },
      sequences: {
        changeFoo: ({ store }) => store.set(state`foo`, 'bar2'),
      },
    }
    const controller = App(app)
    controller.getSequence('changeFoo')()
    assert.strictEqual(grabbedValue, 'bar2')
  })

  it('should watch computed state', () => {
    let grabbedValue = 0
    const foo = Reaction({ fooCopy: state`fooCopy` }, ({ fooCopy }) => {
      grabbedValue = fooCopy
    })
    const app = {
      reactions: { foo },
      state: {
        foo: 'bar',
        fooCopy: (get) => get(state`foo`),
      },
      sequences: {
        changeFoo: ({ store }) => store.set(state`foo`, 'bar2'),
      },
    }
    const controller = App(app)
    controller.getSequence('changeFoo')()
    assert.strictEqual(grabbedValue, 'bar2')
  })

  it('should grab state dynamically', () => {
    let grabbedValue = null
    const foo = Reaction({ foo: state`foo` }, ({ foo, get }) => {
      grabbedValue = foo + get(state`bar`)
    })
    const app = {
      reactions: { foo },
      state: {
        foo: 'bar',
        bar: 'baz',
      },
      sequences: {
        changeFoo: ({ store }) => store.set(state`foo`, 'bar2'),
      },
    }
    const controller = App(app)
    controller.getSequence('changeFoo')()
    assert.strictEqual(grabbedValue, 'bar2baz')
  })

  // ModuleState tests
  it('should watch module state', () => {
    let grabbedValue = 0
    const foo = Reaction({ foo: moduleState`foo` }, ({ foo }) => {
      grabbedValue = foo
    })
    const app = {
      reactions: { foo },
      state: { foo: 'bar' },
      sequences: {
        changeFoo: ({ store }) => store.set(state`foo`, 'bar2'),
      },
    }
    const controller = App(app)
    controller.getSequence('changeFoo')()
    assert.strictEqual(grabbedValue, 'bar2')
  })

  it('should watch module state with submodule', () => {
    let grabbedValue = 0
    const fooReaction = Reaction({ foo: moduleState`foo` }, ({ foo }) => {
      grabbedValue = foo
    })
    const app = {
      state: {},
      modules: {
        baz: {
          reactions: { fooReaction },
          state: { foo: 'bar' },
          sequences: {
            changeFoo: ({ store }) => store.set(state`baz.foo`, 'bar2'),
          },
        },
      },
    }
    const controller = App(app)
    controller.getSequence('baz.changeFoo')()
    assert.strictEqual(grabbedValue, 'bar2')
  })

  // Tests for static modules with moduleState
  it('should support moduleState tag in static module reactions', () => {
    const calls = []
    const app = App({
      modules: {
        users: {
          state: {
            list: ['user1', 'user2'],
            filter: 'all',
          },
          reactions: {
            watchListWithState: Reaction(
              {
                list: moduleState`list`,
                filter: moduleState`filter`,
              },
              ({ list, filter }) => {
                calls.push({ list, filter })
              }
            ),
          },
          sequences: {
            updateList: ({ store }) =>
              store.set(moduleState`list`, ['user1', 'user2', 'user3']),
            updateFilter: ({ store }) =>
              store.set(moduleState`filter`, 'active'),
          },
        },
      },
    })

    // Verify reaction is not triggered on initialization
    assert.strictEqual(calls.length, 0)

    // Trigger state changes and verify reaction updates
    app.getSequence('users.updateList')()
    assert.strictEqual(calls.length, 1)
    assert.deepStrictEqual(calls[0].list, ['user1', 'user2', 'user3'])
    assert.strictEqual(calls[0].filter, 'all')

    app.getSequence('users.updateFilter')()
    assert.strictEqual(calls.length, 2)
    assert.deepStrictEqual(calls[1].list, ['user1', 'user2', 'user3'])
    assert.strictEqual(calls[1].filter, 'active')
  })

  // Tests for dynamic modules with moduleState
  it('should support moduleState tag in dynamic module reactions', () => {
    const calls = []
    const app = App({ state: {} })

    app.addModule('dynamicModule', {
      state: {
        items: ['item1', 'item2'],
        status: 'pending',
      },
      reactions: {
        stateReaction: Reaction(
          {
            items: moduleState`items`,
            status: moduleState`status`,
          },
          ({ items, status }) => {
            calls.push({ items, status })
          }
        ),
      },
      sequences: {
        updateItems: ({ store }) =>
          store.set(moduleState`items`, ['item1', 'item2', 'item3']),
        updateStatus: ({ store }) =>
          store.set(moduleState`status`, 'completed'),
      },
    })

    // Verify reaction is not triggered on initialization
    assert.strictEqual(calls.length, 0)

    // Trigger state changes and verify reaction updates
    app.getSequence('dynamicModule.updateItems')()
    assert.strictEqual(calls.length, 1)
    assert.deepStrictEqual(calls[0].items, ['item1', 'item2', 'item3'])
    assert.strictEqual(calls[0].status, 'pending')

    app.getSequence('dynamicModule.updateStatus')()
    assert.strictEqual(calls.length, 2)
    assert.deepStrictEqual(calls[1].items, ['item1', 'item2', 'item3'])
    assert.strictEqual(calls[1].status, 'completed')

    app.removeModule('dynamicModule')
  })

  // Test for cross-module reactions
  it('should trigger reactions watching state from multiple modules', () => {
    const calls = []
    const app = App({
      state: {
        rootValue: 'root',
      },
      modules: {
        moduleA: {
          state: {
            valueA: 'A',
          },
          sequences: {
            updateA: ({ store }) => store.set(state`moduleA.valueA`, 'A2'),
          },
        },
        moduleB: {
          state: {
            valueB: 'B',
          },
          reactions: {
            crossModuleWatch: Reaction(
              {
                root: state`rootValue`,
                valueA: state`moduleA.valueA`,
                valueB: state`moduleB.valueB`,
              },
              ({ root, valueA, valueB }) => {
                calls.push(`${root}-${valueA}-${valueB}`)
              }
            ),
          },
          sequences: {
            updateB: ({ store }) => store.set(state`moduleB.valueB`, 'B2'),
          },
        },
      },
    })

    // Verify reaction updates with changes from different modules
    assert.strictEqual(calls.length, 0)

    app.getSequence('moduleA.updateA')()
    assert.strictEqual(calls.length, 1)
    assert.strictEqual(calls[0], 'root-A2-B')

    app.getSequence('moduleB.updateB')()
    assert.strictEqual(calls.length, 2)
    assert.strictEqual(calls[1], 'root-A2-B2')
  })

  // Test for dependency tracking with moduleState
  it('should correctly track dependencies with moduleState', () => {
    let valueReceived = null
    const app = App({
      modules: {
        test: {
          state: {
            count: 0,
          },
          reactions: {
            countWatcher: Reaction(
              {
                withState: state`test.count`,
                withModuleState: moduleState`count`,
              },
              ({ withState, withModuleState }) => {
                valueReceived = {
                  state: withState,
                  moduleState: withModuleState,
                }
              }
            ),
          },
        },
      },
    })

    app.getModel().set(['test', 'count'], 5)
    app.flush()

    // Verify both approaches received the same updated value
    assert.ok(valueReceived !== null, 'Reaction should be triggered')
    assert.strictEqual(valueReceived.state, 5)
    assert.strictEqual(valueReceived.moduleState, 5)
  })

  // Test with model direct changes
  it('should support moduleState tag with explicit flush', () => {
    let result = null
    const app = App({
      modules: {
        users: {
          state: {
            value: 'initial',
          },
          reactions: {
            test: Reaction({ value: moduleState`value` }, ({ value }) => {
              result = value
            }),
          },
        },
      },
    })

    app.getModel().set(['users', 'value'], 'updated')
    app.flush()
    assert.strictEqual(result, 'updated')
  })
})
